import{_ as n,c as i,o as d,ah as l,j as o,a as e}from"./chunks/framework.BkHe6ehV.js";const T=JSON.parse('{"title":"AppWorld 相关论文总结","description":"","frontmatter":{"title":"AppWorld 相关论文总结","date":"2026-07-13T00:00:00+08:00","create":"2026-02-03 20:23:29","categories":["Appworld-Summary"],"tags":["AppWorld","AgentRL","Process-Reward","Skill","Memory","Context-Engineering","Agent-Architecture"],"readingStats":{"words":12238,"minutes":43,"images":0}},"headers":[],"relativePath":"posts/domain/appworld/05-appworld-list.md","filePath":"posts/domain/appworld/05-appworld-list.md","lastUpdated":1785944275000}'),r={name:"posts/domain/appworld/05-appworld-list.md"},s={class:"custom-block tip"},a={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},c={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"9.01ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 3982.2 1000","aria-hidden":"true"};function g(u,t,k,m,v,p){return d(),i("div",null,[t[10]||(t[10]=l('<h1 id="appworld-相关工作分类总结" tabindex="-1">AppWorld 相关工作分类总结 <a class="header-anchor" href="#appworld-相关工作分类总结" aria-label="Permalink to &quot;AppWorld 相关工作分类总结&quot;">​</a></h1><blockquote><p>整理范围：本地 <code>AppWorld相关论文</code> 目录中的 21 篇论文。<br> 时间格式：<code>(YYMM)</code>，例如 <code>(2605)</code> 表示 2026 年 5 月。<br> 详细笔记：<a href="./01-appworld-rl.html">AgentRL</a>、<a href="./02-appworld-agent.html">Agent架构</a>、<a href="./03-appworld-context.html">上下文与记忆</a>、<a href="./04-appworld-synthesis-data.html">合成数据</a>、<a href="./09-appworld-skill.html">Skill与经验知识</a>。</p></blockquote><p>🌺 <strong>总结摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">核心结论</div><ul><li>这份笔记按照<code>能力提升发生的位置</code>组织相关工作，而不是按模型或论文时间简单罗列。八条细分路线可进一步归纳为<code>Policy-Centric AgentRL、Data-Centric Training、External Knowledge &amp; Context、System-Centric Agent</code>四类主流范式。</li><li>与本文最直接相关的是三类Policy训练方法：<code>普通Outcome AgentRL</code>、<code>Step Credit与Process Reward</code>、<code>训练期经验与Skill增强RL</code>。其中，LOOP只使用Outcome Reward；SALT重新分配Outcome Advantage但<code>不使用Process Reward</code>；GVPO显式引入执行过程信号；SIRI、Skill-SD、SAGE和AgentEvolver则在训练中利用Skill或经验。</li><li>Skill+RL方法的部署形态并不相同：<code>SIRI和Skill-SD最终删除Skill Bank</code>，<code>SAGE推理期继续使用外部Skill Library</code>，AgentEvolver完整系统也会检索历史经验。因此，训练方式相似不等于推理成本和模型内化程度相同。</li><li>本文定位为<code>Simple and Strong Outcome AgentRL</code>：采用DAPO <code>Token-Level Loss（Token-mean）</code>与Env Loss Mask，混合L1/L2/L3任务进行<code>n=32 Strict On-policy</code>训练，使用Exact Binary Outcome、KL稳定约束、错误轨迹隔离和Fake Data处理，并允许<code>LLM单次生成不设独立上限</code>。</li><li>横向比较时必须区分<code>Policy参数能力</code>与<code>外部系统能力</code>，同时标明<code>Test-N/Test-C</code>、<code>TGC/SGC</code>、<code>mean@1/mean@k</code>及测试协议。Skill、Memory、Retriever、Planner或多Agent系统带来的增益不能直接归因于Policy训练。</li></ul></div><h2 id="分类介绍" tabindex="-1">分类介绍 <a class="header-anchor" href="#分类介绍" aria-label="Permalink to &quot;分类介绍&quot;">​</a></h2><p>分类的核心依据是<strong>主要创新作用于Agent生命周期的哪个位置</strong>。为兼顾整体理解和具体检索，本节先将相关工作归纳为四类主流范式，再保留八类细分技术路线。同一工作可能同时包含任务生成、经验检索和Policy优化，但本笔记只保留一个主类别，并在具体条目中注明辅助机制和推理期依赖。</p><h3 id="四类主流方法概览" tabindex="-1">四类主流方法概览 <a class="header-anchor" href="#四类主流方法概览" aria-label="Permalink to &quot;四类主流方法概览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主流范式</th><th>覆盖的八类细分</th><th>核心含义</th><th>主要优点</th><th>主要缺点</th><th>代表工作</th></tr></thead><tbody><tr><td><strong>Policy-Centric AgentRL</strong></td><td>普通Outcome AgentRL；Step Credit与Process Reward；训练期经验与Skill增强RL</td><td>通过Outcome、过程信号、Skill或经验直接更新Agent Policy</td><td><strong>能力进入模型参数</strong>；多数方法推理路径简单；适合分析Policy本身的提升</td><td>环境Rollout昂贵，长轨迹信用分配和训练稳定性困难；Skill增强方法还可能依赖Teacher或外部Skill</td><td><strong>(2606) GVPO、SIRI；(2604) Skill-SD；(2602) 本文；(2512) SAGE；(2502) LOOP</strong></td></tr><tr><td><strong>Data-Centric Training</strong></td><td>任务合成与数据演化</td><td>扩展训练任务，或根据当前Policy弱点动态更新任务分布</td><td><strong>扩大任务覆盖并形成课程</strong>；数据生成模块通常不进入推理路径</td><td>任务生成、重执行和Verifier成本高；容易产生重复、无效或分布偏移的数据</td><td><strong>(2605) CoEvolve；(2512) CuES</strong></td></tr><tr><td><strong>External Knowledge &amp; Context</strong></td><td>Skill Library构建与治理；Memory与In-Context Experience；上下文压缩</td><td>在推理时检索Skill/Memory，或压缩与重组长上下文</td><td><strong>无需反复更新Agent Policy</strong>；知识更新快，能够复用历史经验并缓解Context压力</td><td>能力依赖外部库、Retriever或Compressor；存在检索错误、信息丢失、Context成本和额外Latency</td><td><strong>(2606) ASSAY、METIS；(2604) SkillX；(2512) ReMe、PAACE；(2510) ACE、ACON</strong></td></tr><tr><td><strong>System-Centric Agent</strong></td><td>多Agent、企业系统与广义规划</td><td>通过角色分工、规划、验证、Sandbox和组件复用增强完整Agent系统</td><td><strong>模块化、可验证、便于错误恢复</strong>；适合复杂Workflow与生产约束</td><td>系统成本和调试复杂度高，错误可能级联；测试协议通常更重，难与单Policy Agent直接比较</td><td><strong>(2605) HCL-GP；(2510) CUGA；(2509) ProST</strong></td></tr></tbody></table><h3 id="八类细分技术路线" tabindex="-1">八类细分技术路线 <a class="header-anchor" href="#八类细分技术路线" aria-label="Permalink to &quot;八类细分技术路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术类型</th><th>主要解决的问题</th><th>是否训练Policy</th><th>推理期额外依赖</th><th>代表工作</th></tr></thead><tbody><tr><td><strong>普通Outcome AgentRL</strong></td><td>如何仅依靠任务结果稳定训练长程Agent</td><td><strong>是</strong></td><td>通常无</td><td><strong>(2602) 本文、(2502) LOOP</strong></td></tr><tr><td><strong>Step Credit与Process Reward</strong></td><td>如何给长轨迹中的Action分配更细粒度的训练信号</td><td><strong>是</strong></td><td>通常无</td><td><strong>(2606) GVPO、(2510) SALT</strong></td></tr><tr><td><strong>训练期经验与Skill增强RL</strong></td><td>如何在RL或蒸馏中利用Skill、Teacher或历史经验</td><td><strong>是</strong></td><td>因方法而异</td><td><strong>(2606) SIRI、(2604) Skill-SD、(2512) SAGE、(2511) AgentEvolver</strong></td></tr><tr><td><strong>任务合成与数据演化</strong></td><td>训练任务从哪里来，以及如何随Policy能力动态更新</td><td><strong>通常训练下游Policy</strong></td><td>生成模块通常不保留</td><td><strong>(2605) CoEvolve、(2512) CuES</strong></td></tr><tr><td><strong>Skill Library构建与治理</strong></td><td>如何构建、检索、筛选和治理可复用Skill</td><td><strong>否</strong></td><td>SkillKB、Retriever或Causal Mask</td><td><strong>(2606) ASSAY、(2604) SkillX</strong></td></tr><tr><td><strong>Memory与In-Context Experience</strong></td><td>如何复用成功轨迹、Playbook和Procedural Memory</td><td><strong>否</strong></td><td>Memory、Retriever及额外Context</td><td><strong>(2606) METIS、(2512) ReMe、(2510) ACE、(2506) Agent ICL</strong></td></tr><tr><td><strong>上下文压缩</strong></td><td>如何在长程交互中降低Context长度并保留决策信息</td><td><strong>不训练Agent Policy</strong></td><td>独立Compressor或Plan模块</td><td><strong>(2512) PAACE、(2510) ACON</strong></td></tr><tr><td><strong>多Agent、企业系统与广义规划</strong></td><td>如何通过角色分工、规划、验证和组件复用提升系统能力</td><td><strong>SFT或不训练</strong></td><td>多Agent、Repository、Verifier或Sandbox</td><td><strong>(2605) HCL-GP、(2510) CUGA、(2509) ProST</strong></td></tr></tbody></table><h3 id="各类方法的当前缺点" tabindex="-1">各类方法的当前缺点 <a class="header-anchor" href="#各类方法的当前缺点" aria-label="Permalink to &quot;各类方法的当前缺点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术类型</th><th>当前主要缺点</th><th>具体风险与对比边界</th></tr></thead><tbody><tr><td><strong>普通Outcome AgentRL</strong></td><td><strong>延迟Reward难以定位错误Action</strong>，长轨迹Rollout与更新成本高</td><td>Binary Outcome在同组全失败或全成功时缺少有效Advantage；训练稳定性对Loss聚合、Clip、KL、轨迹复用和生成截断较敏感</td></tr><tr><td><strong>Step Credit与Process Reward</strong></td><td><strong>细粒度信号不一定等价于真实因果贡献</strong></td><td>Trajectory Graph、执行成功率或人工规则都可能引入偏差；Process Signal依赖环境反馈，跨环境迁移和额外计算成本仍未充分验证</td></tr><tr><td><strong>训练期经验与Skill增强RL</strong></td><td><strong>训练链路复杂，容易依赖Teacher、Summarizer或Skill质量</strong></td><td>可能出现Teacher–Student Off-policy、Train/Test Prompt不一致和错误Skill放大；SAGE推理期仍保留Skill Library，SIRI无AppWorld结果，现有实验口径并不统一</td></tr><tr><td><strong>任务合成与数据演化</strong></td><td><strong>高质量任务生成与验证成本高</strong></td><td>容易产生重复、不可执行或偏离真实分布的任务；能力上限受外部生成模型和Verifier限制，部分工作对下游RL配置披露不足</td></tr><tr><td><strong>Skill Library构建与治理</strong></td><td><strong>能力主要保存在外部库中，没有证明Policy完成内化</strong></td><td>错误检索或有害Skill可能降低性能；Skill构建、因果归因和逐任务Mask需要大量额外Rollout，随Skill与Task数量增长时扩展成本高</td></tr><tr><td><strong>Memory与In-Context Experience</strong></td><td><strong>检索噪声、Memory过时与Context膨胀并存</strong></td><td>成功经验不一定适配新任务，失败经验可能污染决策；效果依赖Retriever、长Context和外部Memory Manager，难与模型参数能力分离</td></tr><tr><td><strong>上下文压缩</strong></td><td><strong>压缩可能永久丢失后续决策所需的信息</strong></td><td>额外Compressor增加训练成本和推理Latency；压缩目标与最终任务成功率可能不一致，部分结果采用自定义Accuracy，难与官方TGC/SGC直接比较</td></tr><tr><td><strong>多Agent、企业系统与广义规划</strong></td><td><strong>系统成本、Latency和调试复杂度最高</strong></td><td>子Agent错误会级联传播，增益难归因到单一模块；Test-time Verifier、多任务联合输入或反复Debug形成非标准协议，不能与逐任务单Policy Agent直接比较</td></tr></tbody></table><div class="custom-block warning"><div class="custom-block-title">跨类别共性瓶颈</div><ul><li><strong>能力归因不清晰</strong>：Policy、外部知识、强Teacher、Verifier和测试时搜索经常同时变化，最终分数无法回答“模型本身学会了多少”。</li><li><strong>评测协议不统一</strong>：<code>Test-N/Test-C</code>、<code>TGC/SGC</code>、<code>Avg@k/Pass@k</code>、Dev/Test、自定义Accuracy及交互预算差异较大，单一分数不适合直接排序。</li><li><strong>成本披露不足</strong>：不少工作没有完整报告训练Rollout、外部模型调用、Skill/Memory构建、测试时重试和总Token成本。</li><li><strong>长期泛化仍不充分</strong>：现有结果主要集中在固定AppWorld环境，Skill、Memory、Process Signal和合成任务能否迁移到新工具、新App和分布外任务仍缺少统一验证。</li></ul></div><div class="custom-block note"><div class="custom-block-title">分类边界</div><ul><li><code>AppWorld</code>是所有工作的Benchmark与评测基础，不计入八条方法路线。</li><li>分类以<code>主要训练或推理机制</code>为准。例如SAGE虽在推理期保留Skill Library，但核心贡献是Skill-integrated RL，因此归入训练期Skill增强RL。</li><li>上方分类表中的代表工作按照时间<code>从近到远</code>排列；实验口径不同的结果只并列展示，不直接据此判断SOTA。</li></ul></div><h2 id="一、工作概览表" tabindex="-1">一、工作概览表 <a class="header-anchor" href="#一、工作概览表" aria-label="Permalink to &quot;一、工作概览表&quot;">​</a></h2><div class="custom-block warning"><div class="custom-block-title">表格阅读口径</div><ul><li>不再单列“类别”，而是直接按<code>相同技术路线</code>分表，避免一张大表中不同方法混排。</li><li><code>学习方式</code>不仅回答是否训练，还说明优化的是<code>Agent Policy、Compressor</code>还是外部Skill/Memory。</li><li><code>训练/构建预算</code>区分RL Rollout与外部知识构建预算；两者不能直接比较。</li><li>关键结果默认写作<code>Test-N TGC/SGC；Test-C TGC/SGC</code>。Avg@4、Pass@4、Dev Accuracy或自定义Acc会明确标记。</li><li><code>推理期依赖</code>用于区分模型参数能力与Skill、Memory、Planner、Compressor等系统能力。</li></ul></div><h3 id="_1-1-基准与评测" tabindex="-1">1.1 基准与评测 <a class="header-anchor" href="#_1-1-基准与评测" aria-label="Permalink to &quot;1.1 基准与评测&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2407) AppWorld</strong></td><td><strong>GPT-4o等</strong></td><td>不训练；构建Benchmark</td><td>250 Scenarios / 750 Tasks</td><td>State-based Unit Tests</td><td>标准环境 + API Docs</td><td>GPT-4o ReAct：N <strong>48.8/32.1</strong>；C <strong>30.2/13.0</strong></td></tr></tbody></table><h3 id="_1-2-普通outcome-agentrl" tabindex="-1">1.2 普通Outcome AgentRL <a class="header-anchor" href="#_1-2-普通outcome-agentrl" aria-label="Permalink to &quot;1.2 普通Outcome AgentRL&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2502) LOOP</strong></td><td><strong>Qwen2.5-32B</strong></td><td>LoRA RL；LOO-PPO</td><td>72 Tasks；<strong>rollout.n=6</strong></td><td>Unit-test Pass Fraction</td><td>无额外模块</td><td>N <strong>71.3/53.6</strong>；C <strong>45.7/26.6</strong></td></tr><tr><td><strong>(2602) 本文</strong></td><td><strong>Qwen3-14B</strong></td><td>Full-parameter GRPO</td><td>90 Tasks；<strong>rollout.n=32</strong></td><td>Exact Binary Outcome</td><td>无辅助Learned/Retrieval模块</td><td>历史官方：N <strong>86.9/80.4</strong>；C <strong>67.6/50.4</strong></td></tr></tbody></table><h3 id="_1-3-step-credit与process-reward" tabindex="-1">1.3 Step Credit与Process Reward <a class="header-anchor" href="#_1-3-step-credit与process-reward" aria-label="Permalink to &quot;1.3 Step Credit与Process Reward&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2510) SALT</strong></td><td><strong>Qwen2.5-32B</strong></td><td>RLOO/GRPO + Trajectory Graph</td><td>任务范围未报告；<strong>n=8</strong></td><td>Binary Outcome；跨轨迹Step匹配</td><td>无额外模块</td><td>N <strong>66.2/47.9</strong>；C <strong>36.8/20.9</strong>；<strong>不是Process Reward</strong></td></tr><tr><td><strong>(2606) GVPO</strong></td><td><strong>Qwen2.5-32B</strong></td><td>GRPO + Advantage Shaping</td><td>72 Tasks；<strong>n=8</strong></td><td>Pass Fraction + Execution Process Signal</td><td>无额外模块</td><td>N <strong>72.6/55.4</strong>；C <strong>49.4/28.8</strong></td></tr></tbody></table><h3 id="_1-4-训练期经验与skill增强rl" tabindex="-1">1.4 训练期经验与Skill增强RL <a class="header-anchor" href="#_1-4-训练期经验与skill增强rl" aria-label="Permalink to &quot;1.4 训练期经验与Skill增强RL&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2606) SIRI</strong></td><td><strong>Qwen2.5-7B</strong></td><td>GiGPO + Skill Internalization</td><td>无AppWorld；<strong>n=8</strong></td><td>Self-mined Skill Utility + Action Advantage</td><td>无；最终删除Skill Bank</td><td>无AppWorld结果；ALFWorld <strong>0.930</strong>，WebShop Success <strong>0.813</strong></td></tr><tr><td><strong>(2604) Skill-SD</strong></td><td><strong>Qwen3-4B</strong></td><td>GRPO + Self-Distillation</td><td>90 Train；<strong>n=4</strong></td><td>Completion Fraction + Skill Teacher</td><td>无；Skill只在训练期</td><td>Dev Acc./Comp. <strong>64.9/84.9</strong>；无Test-N/C</td></tr><tr><td><strong>(2512) SAGE / SkillRL</strong></td><td><strong>Qwen2.5-32B</strong></td><td>SFT + Skill-integrated RL</td><td>1,129 SFT样本；72 RL Tasks；<strong>n=8</strong></td><td>Completion + Skill Generation/Reuse Bonus</td><td>Skill Library + Retriever</td><td>N <strong>72.0/60.7</strong>；C <strong>50.1/32.4</strong></td></tr><tr><td><strong>(2511) AgentEvolver</strong></td><td><strong>Qwen2.5-7B/14B</strong></td><td>Self-evolving RL</td><td>主任务规模与<strong>n</strong>未完整报告</td><td>Outcome/Judge + Experience + Step Attribution</td><td>完整系统可检索经验；另有内化消融</td><td>14B N <strong>48.7 Avg@8 / 69.4 Best@8</strong></td></tr></tbody></table><h3 id="_1-5-任务合成与数据演化" tabindex="-1">1.5 任务合成与数据演化 <a class="header-anchor" href="#_1-5-任务合成与数据演化" aria-label="Permalink to &quot;1.5 任务合成与数据演化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2512) CuES</strong></td><td><strong>Qwen2.5-14B</strong></td><td>合成数据 + 下游SFT/RL</td><td>90原始→625合成任务</td><td>环境探索 + 重执行验证</td><td>无合成模块</td><td>N TGC <strong>45.24</strong> Greedy；无SGC/Test-C；RL细节不足</td></tr><tr><td><strong>(2605) CoEvolve</strong></td><td><strong>Qwen2.5-7B；Qwen3-4B/30B-A3B</strong></td><td>动态数据 + GRPO</td><td>100初始任务；<strong>n=8</strong>；每10 Steps更新</td><td>Binary Outcome + Forgetting/Boundary/Rare Signal</td><td>无数据生成模块</td><td>30B：N <strong>54.76/33.93</strong>；C <strong>31.65/16.55</strong></td></tr></tbody></table><h3 id="_1-6-skill-library构建与治理" tabindex="-1">1.6 Skill Library构建与治理 <a class="header-anchor" href="#_1-6-skill-library构建与治理" aria-label="Permalink to &quot;1.6 Skill Library构建与治理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2604) SkillX</strong></td><td><strong>GLM-4.6构建；Qwen3-32B/Kimi-K2/GLM执行</strong></td><td>不训练Policy；构建SkillKB</td><td>90 Tasks；每Task <strong>4+1</strong>条构建/探索轨迹</td><td>Planning/Functional/Atomic Skill</td><td>SkillKB + Retriever + Pseudo-plan</td><td>GLM N <strong>64.88 Avg@4 / 88.69 Pass@4</strong></td></tr><tr><td><strong>(2606) ASSAY</strong></td><td><strong>GPT-5.x、DeepSeek-V3.2等</strong></td><td>不训练；Skill因果治理</td><td>90 Train + 15 Dev；每模型180条归因Rollout</td><td>Skill×Task Randomized Attribution</td><td>Skill Library + Per-task Causal Masking</td><td>DeepSeek N/C TGC <strong>83.3/69.3</strong>；高预算外部治理</td></tr></tbody></table><h3 id="_1-7-memory与in-context-experience" tabindex="-1">1.7 Memory与In-Context Experience <a class="header-anchor" href="#_1-7-memory与in-context-experience" aria-label="Permalink to &quot;1.7 Memory与In-Context Experience&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2506) Agent ICL</strong></td><td><strong>GPT-4o</strong></td><td>不训练；Trajectory ICL</td><td>Train+Dev 147 Tasks；141条成功ReAct轨迹</td><td>完整成功Trajectory</td><td>Trajectory Pool + Retriever + 大Context</td><td>N <strong>65.8/53.6</strong>；C <strong>38.7/24.8</strong></td></tr><tr><td><strong>(2510) ACE</strong></td><td><strong>DeepSeek-V3.1-671B</strong></td><td>不训练；增量Playbook优化</td><td>90 Train + 57 Dev；最多5 Epoch</td><td>Trajectory/Test Feedback</td><td>Generator + Reflector + Curator + Playbook</td><td>Offline N <strong>76.2/64.3</strong>；C <strong>57.3/39.6</strong></td></tr><tr><td><strong>(2512) ReMe</strong></td><td><strong>Qwen3-8B/14B/32B</strong></td><td>不训练；Procedural Memory</td><td>90 Tasks；每Task 8条构建轨迹</td><td>成功/失败/对比经验</td><td>Vector DB + Rerank + Rewrite + Reflection</td><td>32B N <strong>42.02 Avg@4 / 63.49 Pass@4</strong></td></tr><tr><td><strong>(2606) METIS</strong></td><td><strong>GPT-4o Executor + Claude Reflector</strong></td><td>不训练；Text/Code Memory</td><td>90 Tasks顺序构建一次</td><td>Plan/Fact/Pitfall + Recurrence-gated Tool</td><td>Memory Manager + Retriever + Sandbox</td><td>Official N TGC <strong>60.1</strong>；无Test-C</td></tr></tbody></table><h3 id="_1-8-上下文压缩" tabindex="-1">1.8 上下文压缩 <a class="header-anchor" href="#_1-8-上下文压缩" aria-label="Permalink to &quot;1.8 上下文压缩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2510) ACON</strong></td><td><strong>GPT-4.1 Agent；Qwen3-8B/14B等Compressor</strong></td><td>仅优化/蒸馏Compressor</td><td>90 Tasks；每Task压缩/不压缩各1条</td><td>执行反馈驱动Compression Guideline</td><td>独立Compressor</td><td>N TGC <strong>56.5</strong>、Peak <strong>7.33K</strong>；可能增加Latency</td></tr><tr><td><strong>(2512) PAACE</strong></td><td><strong>GPT-OSS-120B Teacher + Qwen3-4B</strong></td><td>仅训练Compressor</td><td>约120万Synthetic Workflows</td><td>Next-k Plan + Outcome-preserving Supervision</td><td>Plan + Qwen3-4B Compressor</td><td>自定义Acc <strong>59.0</strong>、Peak <strong>6.23K</strong>；不是官方TGC/SGC</td></tr></tbody></table><h3 id="_1-9-多agent、企业系统与广义规划" tabindex="-1">1.9 多Agent、企业系统与广义规划 <a class="header-anchor" href="#_1-9-多agent、企业系统与广义规划" aria-label="Permalink to &quot;1.9 多Agent、企业系统与广义规划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间 / 工作</th><th>Backbone</th><th>学习方式</th><th>训练/构建预算</th><th>Reward / 知识来源</th><th>推理期依赖</th><th>关键结果与口径</th></tr></thead><tbody><tr><td><strong>(2509) ProST</strong></td><td><strong>Qwen2.5-Coder 7B/14B/32B等</strong></td><td>多Agent SFT</td><td>Train+Dev 147 Tasks；2,708条多Agent轨迹</td><td>验证后的多角色Trajectory</td><td>Orchestrator + Executor + Critic</td><td>Phi-4：N <strong>46.4/28.6</strong>；C <strong>17.8/8.6</strong></td></tr><tr><td><strong>(2510) CUGA</strong></td><td><strong>GPT-4.1</strong></td><td>不训练；系统编排</td><td>无AppWorld训练</td><td>Planner/Ledger + Tool Feedback</td><td>多子Agent + Retriever + Sandbox + Retry</td><td>N <strong>73.2/62.5</strong>；C <strong>57.6/48.2</strong></td></tr><tr><td><strong>(2605) HCL-GP</strong></td><td><strong>Claude Sonnet 4.6；GPT-OSS-120B</strong></td><td>不训练；Policy/Component Synthesis</td><td>90 Tasks→159 Seed Components</td><td>Scenario多任务结构 + Component Reuse</td><td>Repository + 多Agent + Test-time Verifier/Debug</td><td>Claude N <strong>98.2/98.2</strong>；C <strong>98.3/97.8</strong>；非标准逐Task协议</td></tr></tbody></table><h3 id="_1-10-rl训练配置专项对比" tabindex="-1">1.10 RL训练配置专项对比 <a class="header-anchor" href="#_1-10-rl训练配置专项对比" aria-label="Permalink to &quot;1.10 RL训练配置专项对比&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">阅读口径</div><ul><li>该表只比较涉及Policy RL的工作；<code>未明确报告</code>表示论文正文与附录均未给出，不能按常见实现补齐。</li><li><code>Loss / Mask</code>区分Loss聚合粒度、Policy Token与Environment Observation是否参与梯度；<code>KL</code>区分Policy–Reference约束和Teacher–Student蒸馏。</li><li><code>单次生成</code>指每个Agent Turn或论文定义的Response上限；它不同于总Context、总Response Budget和最大交互轮数。</li></ul></div><table tabindex="0"><thead><tr><th>工作</th><th>Loss / Mask</th><th>Clip / KL / Entropy</th><th>Reward / Advantage</th><th>Policy、数据与Rollout</th><th>生成预算与异常轨迹</th></tr></thead><tbody><tr><td><strong>(2602) 本文</strong></td><td><strong>DAPO Token-Level Loss（Token-mean）；Env Loss Mask，仅Policy Token</strong></td><td><strong>Clip 0.2/0.2；KL 1e-4；No Entropy Reward</strong></td><td><strong>Exact Binary 1/0；无中间Reward与中间Advantage</strong></td><td><strong>Strict On-policy；L1/L2/L3混合；n=32；Thinking</strong></td><td><strong>Env返回4K/turn；LLM单次生成无独立上限；总Response Cap 32K；错误轨迹丢弃 + Fake Data</strong></td></tr><tr><td><strong>(2502) LOOP</strong></td><td><strong>Per-token PPO Ratio；每轨迹仅对Agent Token取均值</strong></td><td><strong>Clip值未报告；无Reference KL；Entropy未报告</strong></td><td><strong>Unit-test Pass Fraction</strong>；Trajectory LOO Advantage</td><td><strong>Rollout Reuse，非Strict On-policy；仅L1/L2；n=6；ReAct CoT</strong></td><td><strong>1.5K/turn；Env返回3K截断</strong>；低Advantage轨迹过滤，超时记失败</td></tr><tr><td><strong>(2606) GVPO</strong></td><td><strong>Sequence-mean-token-mean；Observation Token置零</strong></td><td><strong>Clip 0.2/0.28；KL 0；Entropy 0</strong></td><td><strong>Pass Fraction + Execution Failure Shaping</strong></td><td>Current-policy Group Rollout；仅L1/L2；<strong>n=8；ReAct CoT</strong></td><td><strong>512/turn；Env返回3K截断</strong>；超预算记失败，不丢弃错误Step</td></tr><tr><td><strong>(2510) SALT</strong></td><td><strong>Action-step Advantage</strong>；Policy Loss粒度与Env Mask未报告</td><td><strong>Clip 0.2；KL 0；Entropy未报告</strong></td><td><strong>Binary Outcome</strong>经Trajectory Graph重分配；<strong>无Process Reward</strong></td><td>GRPO/RLOO Group Rollout；任务难度未报告；<strong>n=8</strong>；Thinking未报告</td><td><strong>1.5K/turn；40 Turns</strong>；异常轨迹处理未报告</td></tr><tr><td><strong>(2606) SIRI</strong></td><td><strong>只蒸馏正Utility、正Advantage Action Token</strong>；GiGPO聚合未报告</td><td><strong>对称Clip但值未报告；含KL但系数未报告；Entropy未报告</strong></td><td>Benchmark Return + Episode/Step Advantage + Skill Utility</td><td>Current-policy Paired Rollout；<strong>无AppWorld；n=8；显式Think/Action格式</strong></td><td><strong>512 Response</strong>；只内化筛选后的正向轨迹，Fake Data未报告</td></tr><tr><td><strong>(2604) Skill-SD</strong></td><td><strong>DAPO Token-Level Loss（Token-mean）；Valid Action Token</strong></td><td><strong>Clip 0.2/0.28；无Policy–Reference KL；SDL Reverse-KL λ=0.001；Entropy 0</strong></td><td><strong>Completion Fraction + Token-level Distillation</strong></td><td><strong>Student-owned On-policy；全部90 Tasks；n=4；ReAct</strong></td><td><strong>Max Response 20,480；40 Turns</strong>；未报告错误轨迹丢弃或Fake Data</td></tr><tr><td><strong>(2512) SAGE / SkillRL</strong></td><td><strong>Token-level Ratio；仅LLM Generation，Environment Mask</strong></td><td><strong>Clip值未报告；KL 0；Entropy未报告</strong></td><td><strong>Completion Fraction + Skill Bonus + No-code Penalty</strong></td><td><strong>Strict On-policy、无PPO Epoch；仅L1/L2；n=8；ReAct</strong></td><td><strong>1.5K/turn；Env返回12K字符截断</strong>；超Context停止，RL错误轨迹/Fake Data未报告</td></tr><tr><td><strong>(2511) AgentEvolver</strong></td><td><strong>Step Advantage广播到Token</strong>；Loss reduction与Env Mask未报告</td><td><strong>Clip 0.28/0.28，正样本High扩至0.6；KL 0.001；Entropy未报告</strong></td><td><strong>Continuous Outcome/Judge + GOOD/BAD Attribution</strong></td><td>Vanilla与Experience-guided各50%；<strong>40 Epochs/update</strong>；存在Prompt Stripping Off-policy Mismatch；<strong>n未报告</strong></td><td><strong>30 Steps；单次Token上限未报告</strong>；合成任务会过滤，RL错误轨迹/Fake Data未报告</td></tr><tr><td><strong>(2605) CoEvolve</strong></td><td>Objective按Trajectory Position求和并以总长度归一；Env Mask未报告</td><td><strong>Clip 0.2/0.28；KL 1e-3；Entropy未报告</strong></td><td><strong>Binary Success 1/0；无Process Advantage</strong></td><td>Current-policy GRPO + 动态任务集；100条初始合成任务；<strong>n=8</strong>；Thinking未报告</td><td><strong>Max Response 4,096；30 Steps</strong>；无效合成任务过滤，RL错误轨迹/Fake Data未报告</td></tr><tr><td><strong>(2512) CuES</strong></td><td><strong>下游Policy Loss与Env Mask均未报告</strong></td><td><strong>Clip、KL、Entropy均未报告</strong></td><td>下游RL Reward/Advantage未报告</td><td>AppWorld 90→625合成任务；算法、On-policy状态、<strong>n</strong>与难度混合均未报告</td><td><strong>20,480仅为数据生成上限</strong>；无效合成任务过滤，RL轨迹处理未报告</td></tr></tbody></table><h2 id="二、基准与评测基础" tabindex="-1">二、基准与评测基础 <a class="header-anchor" href="#二、基准与评测基础" aria-label="Permalink to &quot;二、基准与评测基础&quot;">​</a></h2><h3 id="_2407-appworld" tabindex="-1">(2407) AppWorld <a class="header-anchor" href="#_2407-appworld" aria-label="Permalink to &quot;(2407) AppWorld&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>既有Tool-use Benchmark通常工具少、调用链短，环境状态也难以稳定复现。</li><li>参考轨迹或文本匹配无法覆盖多种正确解法，也难检测Agent造成的额外副作用。</li><li><strong>Motivation</strong>：构建一个可重置、Stateful、跨App并能直接验证最终状态的长程Agent环境。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>模拟Gmail、Amazon、Spotify、Venmo等<code>9个App</code>，共<code>457个API</code>。</li><li>每个Scenario实例化<code>3个Contrastive Task</code>。</li><li>使用<code>State-based Unit Tests</code>检查任务目标、最终答案和Collateral Damage。</li><li>定义<code>TGC</code>与更严格的<code>SGC</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>数据规模</strong>：<code>250 Scenarios、750 Tasks</code>；Train 105、Dev 60、Test-N 168、Test-C 417。</li><li>Test-N/Test-C平均涉及1.5/2.0个App、8.2/10.5个Unique API。</li><li>基线包含ReAct、Plan-and-Execute、Full Code+Reflexion、CodeAct等；模型包含GPT-4o、GPT-4 Turbo、Llama-3等。</li><li>该论文不训练权重，<code>rollout.n</code>与RL Reward不适用。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>GPT-4o + ReAct：Test-N <code>48.8/32.1 TGC/SGC</code>，Test-C <code>30.2/13.0</code>。</li><li>GPT-4o的TGC从Level-1 <code>58.3</code>降至Level-3 <code>21.0</code>。</li><li>Oracle API Retrieval仅把Test-N/Test-C TGC提高到<code>54.8/35.2</code>，说明瓶颈不只是API检索。</li></ul></div><h2 id="三、普通outcome-agentrl" tabindex="-1">三、普通Outcome AgentRL <a class="header-anchor" href="#三、普通outcome-agentrl" aria-label="Permalink to &quot;三、普通Outcome AgentRL&quot;">​</a></h2><h3 id="_2502-loop-reinforcement-learning-for-long-horizon-interactive-llm-agents" tabindex="-1">(2502) LOOP: Reinforcement Learning for Long-Horizon Interactive LLM Agents <a class="header-anchor" href="#_2502-loop-reinforcement-learning-for-long-horizon-interactive-llm-agents" aria-label="Permalink to &quot;(2502) LOOP: Reinforcement Learning for Long-Horizon Interactive LLM Agents&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>AppWorld需要数十轮Stateful Python交互，Instruction Model没有针对环境目标进行训练。</li><li>标准PPO需要Policy、Reference、Critic等多份大模型，32B训练成本高。</li><li><strong>Motivation</strong>：只用任务完成Reward训练单Policy，并研究长轨迹中哪种更新粒度最稳定。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Leave-One-Out Advantage + PPO Clip + Rollout Reuse</code>。</li><li>比较<code>Per-trajectory / Per-turn / Per-token Importance Ratio</code>。</li><li>只对<code>Agent生成Token</code>计算Loss；推理时没有Planner、Memory或Skill Library。</li></ul></div>',47)),o("div",s,[t[9]||(t[9]=o("div",{class:"custom-block-title"},"实验设置",-1)),o("ul",null,[t[6]||(t[6]=o("li",null,[o("strong",null,"模型"),e("："),o("code",null,"Qwen2.5-32B-Instruct"),e("；LoRA Rank 16、Alpha 32。")],-1)),t[7]||(t[7]=o("li",null,[o("strong",null,"训练数据"),e("：L1/L2共"),o("code",null,"24 Scenarios、72 Tasks"),e("；每轮抽40 Tasks。")],-1)),o("li",null,[t[2]||(t[2]=e("Unit-test Pass Fraction Reward，")),o("mjx-container",a,[(d(),i("svg",c,t[0]||(t[0]=[l('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="mi"><path data-c="1D445" d="M230 637Q203 637 198 638T193 649Q193 676 204 682Q206 683 378 683Q550 682 564 680Q620 672 658 652T712 606T733 563T739 529Q739 484 710 445T643 385T576 351T538 338L545 333Q612 295 612 223Q612 212 607 162T602 80V71Q602 53 603 43T614 25T640 16Q668 16 686 38T712 85Q717 99 720 102T735 105Q755 105 755 93Q755 75 731 36Q693 -21 641 -21H632Q571 -21 531 4T487 82Q487 109 502 166T517 239Q517 290 474 313Q459 320 449 321T378 323H309L277 193Q244 61 244 59Q244 55 245 54T252 50T269 48T302 46H333Q339 38 339 37T336 19Q332 6 326 0H311Q275 2 180 2Q146 2 117 2T71 2T50 1Q33 1 33 10Q33 12 36 24Q41 43 46 45Q50 46 61 46H67Q94 46 127 49Q141 52 146 61Q149 65 218 339T287 628Q287 635 230 637ZM630 554Q630 586 609 608T523 636Q521 636 500 636T462 637H440Q393 637 386 627Q385 624 352 494T319 361Q319 360 388 360Q466 361 492 367Q556 377 592 426Q608 449 619 486T630 554Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(1036.8,0)"><path data-c="2208" d="M84 250Q84 372 166 450T360 539Q361 539 377 539T419 540T469 540H568Q583 532 583 520Q583 511 570 501L466 500Q355 499 329 494Q280 482 242 458T183 409T147 354T129 306T124 272V270H568Q583 262 583 250T568 230H124V228Q124 207 134 177T167 112T231 48T328 7Q355 1 466 0H570Q583 -10 583 -20Q583 -32 568 -40H471Q464 -40 446 -40T417 -41Q262 -41 172 45Q84 127 84 250Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(1981.6,0)"><path data-c="5B" d="M118 -250V750H255V710H158V-210H255V-250H118Z" style="stroke-width:3;"></path></g><g data-mml-node="mn" transform="translate(2259.6,0)"><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(2759.6,0)"><path data-c="2C" d="M78 35T78 60T94 103T137 121Q165 121 187 96T210 8Q210 -27 201 -60T180 -117T154 -158T130 -185T117 -194Q113 -194 104 -185T95 -172Q95 -168 106 -156T131 -126T157 -76T173 -3V9L172 8Q170 7 167 6T161 3T152 1T140 0Q113 0 96 17Z" style="stroke-width:3;"></path></g><g data-mml-node="mn" transform="translate(3204.2,0)"><path data-c="31" d="M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(3704.2,0)"><path data-c="5D" d="M22 710V750H159V-250H22V-210H119V710H22Z" style="stroke-width:3;"></path></g></g></g>',1)]))),t[1]||(t[1]=o("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[o("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[o("mi",null,"R"),o("mo",null,"∈"),o("mo",{stretchy:"false"},"["),o("mn",null,"0"),o("mo",null,","),o("mn",null,"1"),o("mo",{stretchy:"false"},"]")])],-1))]),t[3]||(t[3]=e("；")),t[4]||(t[4]=o("code",null,"rollout.n=6",-1)),t[5]||(t[5]=e("。"))]),t[8]||(t[8]=l("<li>训练最多40轮，评测最多50轮；LR <code>5e-5</code>；16×H100；最佳Run约42小时。</li><li><strong>Loss / Mask</strong>：使用<code>Per-token Importance Ratio</code>，每条轨迹只对Agent生成Token求平均；这不同于DAPO跨Batch直接Token-mean。</li><li><strong>Regularization</strong>：论文没有给出Clip数值；LOOP本身不维护Reference KL，Entropy Bonus/Reward未报告。</li><li><strong>Policy / Data</strong>：同批轨迹会被多次更新复用，因此<code>不是Strict On-policy</code>；只训练L1/L2，论文明确报告加入L3反而下降。</li><li><strong>Generation / Invalid</strong>：每轮LLM最多<code>1,500 Tokens</code>，API Response超过<code>3K Tokens</code>截断；低Advantage轨迹会过滤，超交互预算记失败，Fake Data处理未报告。</li>",5))])]),t[11]||(t[11]=l('<div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>LOOP-token：Test-N <code>71.3/53.6</code>，Test-C <code>45.7/26.6</code>。</li><li>LOOP-bandit/turn/token的Test-N TGC为<code>53.3/64.1/71.3</code>。</li><li>加入Reward Std Normalization后，Test-N TGC从<code>71.3</code>降至<code>61.9</code>。</li><li>行为上更常查询API Docs，减少Open-loop代码和无依据假设。</li></ul></div><h2 id="四、过程反馈与细粒度信用分配" tabindex="-1">四、过程反馈与细粒度信用分配 <a class="header-anchor" href="#四、过程反馈与细粒度信用分配" aria-label="Permalink to &quot;四、过程反馈与细粒度信用分配&quot;">​</a></h2><h3 id="_2510-salt-step-level-advantage-assignment-via-trajectory-graph" tabindex="-1">(2510) SALT: Step-level Advantage Assignment via Trajectory Graph <a class="header-anchor" href="#_2510-salt-step-level-advantage-assignment-via-trajectory-graph" aria-label="Permalink to &quot;(2510) SALT: Step-level Advantage Assignment via Trajectory Graph&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>GRPO/RLOO把同一个终局Advantage广播给整条轨迹，无法区分有益、无关和错误步骤。</li><li>同一合理动作可能在成功轨迹中被奖励、在失败轨迹中被惩罚，形成Credit Conflict。</li><li><strong>Motivation</strong>：不引入Process Reward Model或Step Label，仅利用同任务多轨迹结构获得Step-level Advantage。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>在同一Rollout Group内构建<code>Trajectory Graph</code>。</li><li>用<code>BGE-M3</code>匹配语义相似的State/Action Edge，并对其原Trajectory Advantage求平均。</li><li><code>独特Step保留原Advantage</code>；构图模块只用于训练。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>Qwen2.5-32B-Instruct</code>；RLOO/GRPO及其SALT版本。</li><li><strong>Reward</strong>：<code>Strict Binary Terminal Reward</code>；<code>rollout.n=8</code>；Minibatch 32。</li><li>最大40轮；LR <code>1e-6</code>；KL 0；100 Steps；Clip 0.2。</li><li>AppWorld训练任务数量、难度组成、GPU和总耗时未完整报告。</li><li><strong>Loss / Mask</strong>：SALT在Action Step层重分配Advantage，但论文没有明确Policy Loss使用Token-mean还是Sequence-mean，也没有明确Environment Token Mask。</li><li><strong>Regularization</strong>：对称Clip <code>0.2/0.2</code>、<code>KL=0</code>；Entropy Bonus/Reward未报告。</li><li><strong>Policy / Data</strong>：按GRPO/RLOO Group Rollout训练，<code>rollout.n=8</code>；是否Fresh On-policy、是否复用轨迹以及L1/L2/L3组成均未明确报告。</li><li><strong>Generation / Invalid</strong>：每轮最多<code>1,500 Tokens</code>、最多40轮；错误/超时轨迹是否丢弃及Fake Data处理未报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>GRPO+SALT：Test-N <code>66.2/47.9</code>，Test-C <code>36.8/20.9</code>。</li><li>普通GRPO：Test-N <code>61.5/41.4</code>，Test-C <code>36.3/17.0</code>。</li><li>Test-N D2 TGC从<code>67.5→76.2</code>，D3从<code>35.5→41.6</code>；但Test-C D1出现下降。</li><li>SALT属于<code>Outcome-only Step Credit</code>，不能写成Process Reward方法。</li></ul></div><h3 id="_2606-gvpo-group-verification-based-policy-optimization" tabindex="-1">(2606) GVPO: Group Verification-based Policy Optimization <a class="header-anchor" href="#_2606-gvpo-group-verification-based-policy-optimization" aria-label="Permalink to &quot;(2606) GVPO: Group Verification-based Policy Optimization&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Outcome Advantage会奖励成功轨迹里的错误Step，也会惩罚失败轨迹里的合理Step。</li><li>Syntax Error、Runtime Exception等确定性环境反馈没有被标准GRPO利用。</li><li><strong>Motivation</strong>：把最终Outcome Verifier与中间Execution Verifier统一进Advantage Shaping。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Unit-test Pass Fraction</code>提供Trajectory Outcome。</li><li>按代码是否成功执行划分<code>Success/Failure Step</code>，对失败Step做条件性负向Shaping。</li><li><code>Observation Token Advantage=0</code>；使用<code>Asymmetric Clip</code>和<code>Sequence-Mean-Token-Mean</code>。</li><li><code>不使用KL与Reward Std Normalization</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型与数据</strong>：<code>Qwen2.5-32B</code>；L1/L2共<code>24 Scenarios、72 Tasks</code>；每轮抽32 Tasks。</li><li><code>rollout.n=8</code>；训练144 Steps；LR <code>1e-5</code>；Clip <code>(0.2,0.28)</code>；Process Penalty <code>b=0.2</code>。</li><li>训练/评测最多40/50轮；8×H100；veRL + FSDP2 + vLLM。</li><li>推理仍是标准单Policy ReAct，不需要Process Reward模块。</li><li><strong>Loss / Mask</strong>：采用<code>Sequence-Mean-Token-Mean</code>；只更新Reasoning/Code Generation Token，Observation Token Advantage置0。</li><li><strong>Regularization</strong>：Asymmetric Clip <code>0.2/0.28</code>，明确<code>不使用KL</code>；Entropy Coefficient为<code>0.0</code>。</li><li><strong>Policy / Data</strong>：Current Behavior Policy产生Group Rollout，未报告PPO式轨迹复用；只训练L1/L2，<code>rollout.n=8</code>，使用ReAct CoT。</li><li><strong>Generation / Invalid</strong>：每轮最多<code>512 Tokens</code>，API Response超过<code>3K Tokens</code>截断；错误Step不会丢弃，而是获得Process Penalty，超预算Episode记失败。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Test-N <code>72.6/55.4</code>，Test-C <code>49.4/28.8</code>。</li><li>相比LOOP，Test-N/Test-C TGC提高<code>1.3/3.7</code>。</li><li>改为Token-mean后Test-C降至<code>34.6/15.1</code>；加回Std Normalization后为<code>42.8/23.7</code>。</li><li><code>b=0.1</code>的单项Test-C TGC为53.1，高于主配置49.4，因此主配置并非每个Split都最优。</li></ul></div><h2 id="五、训练期经验与skill增强rl" tabindex="-1">五、训练期经验与Skill增强RL <a class="header-anchor" href="#五、训练期经验与skill增强rl" aria-label="Permalink to &quot;五、训练期经验与Skill增强RL&quot;">​</a></h2><h3 id="_2606-siri-self-internalizing-rl-with-intrinsic-skills" tabindex="-1">(2606) SIRI: Self-Internalizing RL with Intrinsic Skills <a class="header-anchor" href="#_2606-siri-self-internalizing-rl-with-intrinsic-skills" aria-label="Permalink to &quot;(2606) SIRI: Self-Internalizing RL with Intrinsic Skills&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>现有Skill Agent常依赖外部模型提炼Skill，并在推理期持续检索Skill Bank。</li><li>从弱Policy的偶然轨迹直接总结Skill容易引入噪声。</li><li><strong>Motivation</strong>：让Policy自己挖掘、验证和内化Skill，最终完全删除Skill Bank。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Phase 0—GiGPO Warmup</code>：先获得可靠成功轨迹。</li><li><code>Phase 1—Skill Mining &amp; Validation</code>：从成功Plain Rollout挖掘Skill，通过Skill/No-Skill配对Rollout估计Utility。</li><li><code>Phase 2—Skill Internalization</code>：只蒸馏正Utility Trajectory中的正Advantage Action Token。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>评测范围</strong>：<code>没有AppWorld实验</code>，只评测ALFWorld与WebShop。</li><li><strong>模型</strong>：<code>Qwen2.5-7B</code>；Batch 16；<code>rollout.n=8</code>；Warmup 30–50 Steps。</li><li>每10 Steps做Skill Mining/Validation；8×A100；Qwen3-0.6B-Embedding仅训练期使用。</li><li>Optimizer、LR、Clip、KL和精确Reward未完整报告。</li><li><strong>Loss / Mask</strong>：GiGPO使用Episode/Step Advantage；内化阶段只蒸馏<code>正Utility + 正Advantage</code>的Action Token，并排除Reasoning与其他Natural-language Token；基础RL Loss聚合未报告。</li><li><strong>Regularization</strong>：论文写明使用对称Clip和KL，但没有报告Clip数值与KL系数；Entropy Bonus/Reward未报告。</li><li><strong>Policy / Data</strong>：Current Policy做Skill/No-Skill Paired Rollout，<code>rollout.n=8</code>；没有AppWorld数据，因而不存在AppWorld三难度混合设置；Prompt显式要求<code>&lt;think&gt;/&lt;action&gt;</code>格式。</li><li><strong>Generation / Invalid</strong>：Max Response Length为<code>512 Tokens</code>；只内化通过Utility Gate的正向轨迹，但没有报告Fake Data机制。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>ALFWorld Success：GiGPO <code>0.908</code>，SkillRL <code>0.899</code>，SIRI <code>0.930</code>。</li><li>WebShop Score/Success：GiGPO <code>0.844/0.728</code>，SIRI <code>0.899/0.813</code>。</li><li>不内化但保留Skill推理为<code>0.898/0.805</code>；完整SIRI无Skill推理为<code>0.899/0.813</code>。</li><li>该论文只能作为训练期Skill内化的相关证据，不能列入AppWorld数值比较。</li></ul></div><h3 id="_2604-skill-sd-skill-conditioned-self-distillation" tabindex="-1">(2604) Skill-SD: Skill-Conditioned Self-Distillation <a class="header-anchor" href="#_2604-skill-sd-skill-conditioned-self-distillation" aria-label="Permalink to &quot;(2604) Skill-SD: Skill-Conditioned Self-Distillation&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>长程Agent只有延迟Outcome Reward，直接把Skill注入Student Prompt容易造成Train/Test不一致。</li><li>由Teacher生成Rollout又会产生Off-policy偏移并导致训练崩溃。</li><li><strong>Motivation</strong>：Skill只给Teacher看，Student始终Plain-Prompt On-policy Rollout，再把Token偏好蒸馏进参数。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>从Trajectory总结<code>成功经验、错误和Workflow</code>，按任务维护Skill Buffer并用UCB选择。</li><li><code>Teacher每轮同步Student参数</code>，但额外看到Skill Prompt。</li><li>对同一批Student Token进行师生重评分，联合<code>GRPO + Importance-weighted Reverse-KL</code>。</li><li>测试时删除<code>Teacher、Summarizer和Skill Bank</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型与数据</strong>：<code>Qwen3-4B-Instruct-2507</code>；AppWorld全部<code>90 Train、57 Dev</code>；最多40轮。</li><li>Reward为验证条件完成比例；<code>rollout.n=4</code>；Train Batch 16；Optimization Epoch 1。</li><li>LR <code>1e-6</code>；Clip <code>(0.2,0.28)</code>；SDL <code>λ=0.001</code>；8×L40S。</li><li>只报告Dev Pass@1/Completion，没有Test-N/Test-C。</li><li><strong>Loss / Mask</strong>：GRPO与SDL都使用DAPO式<code>Token-Level Loss（Token-mean）</code>，只统计Valid Action Token；Student生成的同一批Token由Teacher重评分。</li><li><strong>Regularization</strong>：Asymmetric Clip <code>0.2/0.28</code>；没有Policy–Reference KL，但有<code>λ=0.001</code>的Teacher–Student Reverse-KL蒸馏项；Entropy Coefficient为<code>0.0</code>。</li><li><strong>Policy / Data</strong>：<code>Student-owned Strict On-policy</code>、每批只更新1 Epoch；混合全部90个L1/L2/L3任务，<code>rollout.n=4</code>，使用ReAct轨迹。</li><li><strong>Generation / Invalid</strong>：Max Response Length为<code>20,480 Tokens</code>、最多40轮；论文没有报告错误轨迹丢弃或Fake Data处理。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Base <code>8.8/39.1</code>，Vanilla GRPO <code>50.9/76.3</code>，Skill-SD <code>64.9/84.9 Accuracy/Completion</code>。</li><li>直接将Skill给Student的Skill-Augmented GRPO只有<code>42.1/76.1</code>。</li><li>Off-policy Teacher Rollout在训练中期崩溃，说明Student-owned On-policy Rollout是关键。</li></ul></div><h3 id="_2512-sage-skillrl-rl-with-skill-library" tabindex="-1">(2512) SAGE / SkillRL: RL with Skill Library <a class="header-anchor" href="#_2512-sage-skillrl-rl-with-skill-library" aria-label="Permalink to &quot;(2512) SAGE / SkillRL: RL with Skill Library&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>仅靠Prompt生成和调用Skill不稳定，普通Per-task RL也无法奖励“任务1生成、任务2复用”的跨任务价值。</li><li><strong>Motivation</strong>：让Policy与Executable Skill Library共同演化，并学习何时生成、保存和调用Skill。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>先用Claude成功轨迹做<code>SFT Warmup</code>。</li><li>RL时将同Scenario两个任务串成<code>Task Chain</code>。</li><li><code>Skill-integrated Reward</code>同时奖励任务完成、Skill Generation和后续Skill Reuse。</li><li>推理期继续维护、检索和执行<code>外部Python Skill</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>Qwen2.5-32B-Instruct</code>，全参数SFT+RL；Teacher为<code>Claude-3.5-Sonnet-v2</code>。</li><li>RL使用L1/L2共24 Scenarios；<code>rollout.n=8</code>；每Step 384 Rollout Units。</li><li>Fresh On-policy；无KL、无Advantage Std；LR <code>1e-6</code>；4×8 H100。</li><li>最多40轮、每轮1,500 Tokens、Context 28,048。</li><li><strong>Loss / Mask</strong>：Policy Objective使用Token-level Ratio，只对LLM Generation计算Loss，Environment Observation显式Mask。</li><li><strong>Regularization</strong>：论文未报告Clip数值；明确<code>KL=0</code>且不做Advantage Std，Entropy Bonus/Reward未报告。</li><li><strong>Reward / Policy</strong>：Reward是Completion Fraction叠加Skill Generation/Reuse Bonus，并对无代码终止施加<code>-1</code>，不是Sparse Binary Outcome-only；训练为<code>Strict On-policy</code>且无PPO Epoch。</li><li><strong>Generation / Invalid</strong>：每轮最多<code>1,500 Tokens</code>，Environment Output超过<code>12,000字符</code>截断；超28,048 Context停止。RL错误轨迹丢弃与Fake Data未报告，只有SFT数据构建明确使用Rejection Sampling。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>SAGE：Test-N <code>72.0/60.7</code>，Test-C <code>50.1/32.4</code>。</li><li>普通GRPO为N <code>69.2/51.8</code>、C <code>40.7/26.9</code>；SFT-only为N <code>55.2/41.7</code>。</li><li>去掉Skill推理后Test-N为<code>71.4/54.8</code>，说明Policy本身和外部Skill都贡献能力。</li></ul></div><h3 id="_2511-agentevolver-towards-efficient-self-evolving-agent-system" tabindex="-1">(2511) AgentEvolver: Towards Efficient Self-Evolving Agent System <a class="header-anchor" href="#_2511-agentevolver-towards-efficient-self-evolving-agent-system" aria-label="Permalink to &quot;(2511) AgentEvolver: Towards Efficient Self-Evolving Agent System&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>AgentRL同时面临训练任务稀缺、重复低价值探索和终局Reward难以归因的问题。</li><li>新环境可能只有工具，没有预定义任务与Verifier。</li><li><strong>Motivation</strong>：自动化<code>环境→任务→经验→反馈</code>闭环，让Agent自己决定学什么、如何探索和如何归因。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Self-Questioning</code>：探索环境、合成任务并重执行验证。</li><li><code>Self-Navigating</code>：检索历史经验引导一半Rollout，更新前移除经验文本并使用<code>Selective Boosting</code>。</li><li><code>Self-Attributing</code>：外部LLM为Action标记<code>GOOD/BAD</code>，与Outcome Advantage组合。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>Qwen2.5-7B/14B-Instruct</code>；GRPO-style；LR <code>1e-6</code>；Batch 32；每次Policy Update 40 Epochs；KL 0.001；8×A100-80G。</li><li>Self-Navigating Top-K 5；经验轨迹比例0.5；Attribution权重<code>α=0.1, β=1</code>。</li><li>评测最多30 Steps，报告Test-N TGC Avg@8/Best@8。</li><li>训练<code>rollout.n</code>和主实验任务规模没有完整披露。</li><li><strong>Loss / Mask</strong>：Step Advantage会广播到该Step的Token，但论文未报告最终Loss Reduction及Environment Observation Mask。</li><li><strong>Regularization</strong>：Vanilla/经验轨迹使用Clip <code>0.28/0.28</code>，正Advantage经验轨迹的Clip-High扩至<code>0.6</code>；KL为<code>0.001</code>，Entropy项未报告。</li><li><strong>Reward / Policy</strong>：不是Sparse Binary Outcome-only；它融合Continuous Outcome/Judge与<code>GOOD/BAD</code> Step Attribution。Vanilla与经验引导轨迹各50%，去掉经验Prompt后形成显式Off-policy Mismatch。</li><li><strong>Generation / Invalid</strong>：最多30 Steps，但单次生成Token上限未报告；合成任务有质量过滤，RL错误轨迹是否丢弃及Fake Data处理未报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>7B：Base <code>1.8/5.6</code> → AgentEvolver <code>32.4/51.2 Avg@8/Best@8</code>。</li><li>14B：Base <code>18.0/31.4</code> → <code>48.7/69.4</code>。</li><li>14B Dev中Vanilla RL为<code>51.5/69.8</code>，Self-Navigating为<code>64.7/85.9</code>。</li><li>方法同时使用任务合成、经验检索和外部Step Attribution，不能视为纯Outcome-only RL。</li></ul></div><h2 id="六、任务合成与数据演化" tabindex="-1">六、任务合成与数据演化 <a class="header-anchor" href="#六、任务合成与数据演化" aria-label="Permalink to &quot;六、任务合成与数据演化&quot;">​</a></h2><h3 id="_2512-cues-curiosity-driven-environment-grounded-synthesis" tabindex="-1">(2512) CuES: Curiosity-driven Environment-grounded Synthesis <a class="header-anchor" href="#_2512-cues-curiosity-driven-environment-grounded-synthesis" aria-label="Permalink to &quot;(2512) CuES: Curiosity-driven Environment-grounded Synthesis&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>新环境常只有工具和接口，没有可直接用于RL的训练任务。</li><li>从人工Seed或外部语料改写，容易生成不可执行、重复或脱离环境能力的任务。</li><li><strong>Motivation</strong>：完全从环境结构和真实交互中生成可执行、相关且多样的训练任务。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Requirement Confirmation</code>提取Concept Pool。</li><li><code>Curious Exploration</code>用环境记忆避免重复探索。</li><li><code>Task Abstraction</code>生成Goal与Action Guideline，随后由Execution Agent重执行验证。</li><li><code>Goal Rewrite</code>改变提示信息和难度，构建训练课程。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>生成模型</strong>：<code>qwen-plus-latest</code>；Temperature 0.7；Max Tokens 20,480。</li><li><strong>探索预算</strong>：每环境<code>500条Exploration Rollout</code>、每条最多30 Steps。</li><li><strong>数据规模</strong>：AppWorld从<code>90个原始任务</code>扩展到<code>625条合成任务</code>。</li><li><strong>执行模型</strong>：<code>Qwen2.5-14B</code>；RL算法、LR、Batch、Epoch、<code>rollout.n</code>和资源未完整报告。</li><li><strong>RL配置披露边界</strong>：论文没有明确下游Policy的Loss/Env Mask、Clip、KL、Entropy、Reward/Advantage、On-policy状态、AppWorld难度混合与Thinking模式。</li><li><strong>Generation / Invalid</strong>：<code>20,480 Tokens</code>是CuES数据生成模型上限，不能写成下游RL Agent的生成上限；候选合成任务只有Reward=1才进入后续阶段，但RL错误轨迹丢弃与Fake Data未报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>AppWorld Test-N：Base <code>11.76 Avg@8 / 14.29 Greedy</code>，CuES <code>45.54/45.24</code>。</li><li>WebShop为<code>63.55/64.10</code>，BFCL-v3为<code>43.00/44.15</code>。</li><li>AppWorld只报告Test-N TGC，无SGC与Test-C。</li></ul></div><h3 id="_2605-coevolve-agent–data-mutual-evolution" tabindex="-1">(2605) CoEvolve: Agent–Data Mutual Evolution <a class="header-anchor" href="#_2605-coevolve-agent–data-mutual-evolution" aria-label="Permalink to &quot;(2605) CoEvolve: Agent–Data Mutual Evolution&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>固定人工或离线合成任务不会随Policy能力变化，容易反复采样已掌握任务并遗漏新弱点。</li><li><strong>Motivation</strong>：从当前Policy Rollout发现遗忘、不稳定边界和低频行为，再定向生成新任务。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>从Rollout提取<code>Forgetting</code>、<code>Boundary</code>和<code>Rare Action Pattern</code>。</li><li><code>Qwen3-Max</code>根据弱点重新探索环境，生成Action–Observation Triplet。</li><li>将Triplet抽象为<code>Task–Solution Pair</code>，经真实环境验证后加入下一轮GRPO训练集。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>Qwen2.5-7B、Qwen3-4B、Qwen3-30B-A3B</code>。</li><li>GRPO <code>rollout.n=8</code>；Batch 32；LR <code>1e-6</code>；Clip <code>(0.2,0.28)</code>；KL 0.001。</li><li>Binary Terminal Reward；初始100条合成任务；训练120 Steps，每10 Steps更新数据。</li><li>4B/7B使用8×H20，30B-A3B使用16×H20。</li><li><strong>Loss / Mask</strong>：目标函数对Trajectory Position求和并按总长度归一；论文没有明确它是否等价于DAPO Token-mean，也没有明确Environment Token Mask。</li><li><strong>Regularization</strong>：Asymmetric Clip <code>0.2/0.28</code>、KL <code>1e-3</code>；Entropy Bonus/Reward未报告。</li><li><strong>Policy / Data</strong>：Current-policy GRPO与动态任务集共同演化，未报告轨迹复用；初始100条合成任务，AppWorld L1/L2/L3组成与Thinking模式未报告，<code>rollout.n=8</code>。</li><li><strong>Generation / Invalid</strong>：Max Response Length为<code>4,096 Tokens</code>、最多30 Steps；验证阶段会过滤无效合成任务，但RL错误轨迹丢弃与Fake Data处理未报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Qwen3-4B Test-N：Zero-shot <code>16.67</code>，GRPO <code>28.57</code>，CoEvolve <code>35.71 TGC</code>。</li><li>Qwen3-30B-A3B：Test-N <code>54.76/33.93</code>，Test-C <code>31.65/16.55</code>。</li><li>4B从Static Data <code>28.57</code>、Random Exploration <code>30.36</code>提升到Feedback-driven <code>35.71</code>。</li><li>去掉Task Validation降至<code>27.38</code>，说明环境验证是关键质量门。</li></ul></div><h2 id="七、skill-library构建与治理" tabindex="-1">七、Skill Library构建与治理 <a class="header-anchor" href="#七、skill-library构建与治理" aria-label="Permalink to &quot;七、Skill Library构建与治理&quot;">​</a></h2><h3 id="_2604-skillx-automatically-constructing-skill-knowledge-bases" tabindex="-1">(2604) SkillX: Automatically Constructing Skill Knowledge Bases <a class="header-anchor" href="#_2604-skillx-automatically-constructing-skill-knowledge-bases" aria-label="Permalink to &quot;(2604) SkillX: Automatically Constructing Skill Knowledge Bases&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Agent在不同任务上重复探索，且只从自身轨迹提取经验会受基座模型能力限制。</li><li>原始Trajectory、Workflow和API Tip难以同时满足可迁移、易检索和可执行。</li><li><strong>Motivation</strong>：由强模型预建可跨Agent复用的Plug-and-Play SkillKB。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>三级Skill</code>：Planning、Functional、Atomic。</li><li>通过<code>Rollout–Extract–Merge/Filter–Add/Modify/Keep</code>迭代精炼。</li><li>针对高失败率或从未调用的Tool做<code>Experience-guided Exploration</code>。</li><li>推理时先生成<code>Pseudo-plan</code>，再按Step检索Functional/Atomic Skill。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>构建模型</strong>：<code>GLM-4.6</code>；每个AppWorld训练任务4条Trajectory，另做1次Exploration。</li><li><strong>执行模型</strong>：<code>Qwen3-32B、Kimi-K2、GLM-4.6</code>；AppWorld 90 Train、168 Test-N。</li><li>Qwen3-Embedding-8B；最多3轮Refinement；最终最多注入8个Skill。</li><li>不训练Agent权重，无RL <code>rollout.n</code>。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Qwen3-32B：No-memory <code>27.68/47.62</code> → SkillX <code>35.12/58.93 Avg@4/Pass@4</code>。</li><li>Kimi-K2：<code>46.88/70.24</code> → <code>56.40/81.55</code>。</li><li>GLM-4.6：<code>60.27/83.33</code> → <code>64.88/88.69</code>。</li><li>不同模型的最佳Skill层级不同，说明Skill不是注入越多越好。</li></ul></div><h3 id="_2606-assay-not-all-skills-help" tabindex="-1">(2606) ASSAY: Not All Skills Help <a class="header-anchor" href="#_2606-assay-not-all-skills-help" aria-label="Permalink to &quot;(2606) ASSAY: Not All Skills Help&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>LLM生成的Skill看起来合理，不代表它在不同任务上都有正效应。</li><li>同一个Skill可能帮助任务A、伤害任务B，Global Average会让正负作用互相抵消。</li><li><strong>Motivation</strong>：用跨任务随机实验测量Skill的条件性因果贡献，并按Task选择Skill。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>在15个Dev Task上<code>随机Mask Skill</code>，估计Skill×Task Difference-in-means Matrix。</li><li>根据<code>Heterogeneity</code>做Split、根据全局低贡献做Retire、根据Embedding做Merge。</li><li>测试时检索Top-8相似Dev Task，预测<code>每个Skill的因果效应</code>并Mask有害Skill。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>数据</strong>：AppWorld <code>90 Train、15 Dev、Test-N 168、Test-C 417</code>。</li><li>每模型额外<code>12×15=180</code>条归因Rollout；Keep Probability 0.4。</li><li>ReAct 40 Steps，Temperature 0；覆盖GPT-5.x、DeepSeek-V3.2、Sonnet 4.5、Gemini 2.5 Pro等。</li><li>不训练模型权重，但推理依赖完整Skill Library和Causal Masking。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>DeepSeek-V3.2：ReAct N/C <code>69.1/47.0</code>，ACE <code>78.0/63.1</code>，ASSAY <code>83.3/69.3 TGC</code>。</li><li>GPT-5.1：ReAct <code>61.9/52.5</code>，ASSAY <code>77.4/66.4</code>。</li><li>GPT-5.1 Test-N顺序消融：ReAct 61.9 → Templates 67.9 → Restructuring 69.9 → Per-task Masking 77.4。</li><li>结果属于高预算外部Skill治理，不能等同于单Policy训练提升。</li></ul></div><h2 id="八、memory与in-context-experience" tabindex="-1">八、Memory与In-Context Experience <a class="header-anchor" href="#八、memory与in-context-experience" aria-label="Permalink to &quot;八、Memory与In-Context Experience&quot;">​</a></h2><h3 id="_2506-leveraging-in-context-learning-for-language-model-agents" tabindex="-1">(2506) Leveraging In-Context Learning for Language Model Agents <a class="header-anchor" href="#_2506-leveraging-in-context-learning-for-language-model-agents" aria-label="Permalink to &quot;(2506) Leveraging In-Context Learning for Language Model Agents&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Agent ICL的瓶颈不只是放几个示例，而是成功轨迹如何获得、选择、裁剪和放置。</li><li>完整长轨迹包含大量与当前任务无关的信息，但局部Snippet又可能缺失完整Workflow。</li><li><strong>Motivation</strong>：系统比较Task/Subtask/Step三种经验粒度。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>迭代标注Train+Dev，建立<code>成功Trajectory Pool</code>。</li><li><code>Task级</code>检索1–2条完整轨迹；<code>Subtask级</code>使用Planner-and-Executor；<code>Step级</code>检索Thought Snippet。</li><li>不更新模型权重，完全依靠<code>推理期ICL与Retriever</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>GPT-4o-2024-08-06</code>；迁移实验使用GPT-4o-mini。</li><li><strong>经验库</strong>：AppWorld Train 90 + Dev 57，得到<code>141条ReAct成功轨迹、134条PnE轨迹和833个Subtask</code>。</li><li>标注Temperature 0.1、Top-p 0.5、50 Steps；评测使用1M Context。</li><li><code>rollout.n</code>与RL Reward不适用。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>GPT-4o ReAct Test-N：Zero-shot <code>35.1/15.2</code>，固定1条轨迹<code>50.6/30.4</code>，Set-BSR选2条为<code>65.8/53.6</code>。</li><li>Test-C为<code>38.7/24.8</code>。</li><li>平均步数从<code>21.9</code>降到<code>11.5</code>；已有完整轨迹后再加Step Snippet几乎无增益。</li><li>两条完整轨迹相对一条平均成本增加约40%。</li></ul></div><h3 id="_2510-ace-agentic-context-engineering" tabindex="-1">(2510) ACE: Agentic Context Engineering <a class="header-anchor" href="#_2510-ace-agentic-context-engineering" aria-label="Permalink to &quot;(2510) ACE: Agentic Context Engineering&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>现有Prompt/Context Optimization容易产生Brevity Bias，或把知识堆入单一长Context造成结构坍塌。</li><li><strong>Motivation</strong>：像维护软件手册一样，持续增量维护结构化Playbook，而不是更新Policy权重。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Generator</code>执行任务，<code>Reflector</code>根据轨迹和反馈诊断，<code>Curator</code>输出Add/Update/Delete Delta。</li><li>通过确定性Merge/Dedup维护<code>Itemized Playbook</code>。</li><li>支持<code>Offline多Epoch</code>和<code>Online Test-time Adaptation</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>DeepSeek-V3.1-671B Non-thinking</code>同时作为Generator/Reflector/Curator。</li><li>AppWorld 90 Train、57 Dev、Test-N/Test-C；Batch 1；最多5轮Reflection与5个Offline Epoch。</li><li>GT版使用Unit-test Outcome，No-GT版使用自然执行成败。</li><li>不训练模型权重；推理持续注入外部Playbook。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>ReAct Test-N/C为<code>63.7/42.9</code>、<code>41.5/21.6 TGC/SGC</code>。</li><li>Offline ACE-GT为N <code>76.2/64.3</code>、C <code>57.3/39.6</code>。</li><li>Online No-GT为N <code>69.6/53.6</code>、C <code>66.0/48.9</code>。</li><li>Online结果包含测试时持续经验更新，不应与Frozen Agent协议直接横比。</li></ul></div><h3 id="_2512-reme-dynamic-procedural-memory" tabindex="-1">(2512) ReMe: Dynamic Procedural Memory <a class="header-anchor" href="#_2512-reme-dynamic-procedural-memory" aria-label="Permalink to &quot;(2512) ReMe: Dynamic Procedural Memory&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Append-only Memory会积累过时或有害经验；整轨迹粒度过粗，直接复用又难适应新任务。</li><li><strong>Motivation</strong>：闭环管理经验获取、适配复用和Utility-based删除，让较小模型通过外部记忆补偿能力。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>从成功、失败和成功–失败对比轨迹提取<code>Keypoint-level经验</code>。</li><li>使用<code>Usage-scenario Embedding</code>检索，并进行Rerank和Task-adaptive Rewrite。</li><li>动态版<code>选择性添加 + 失败反思 + Utility-based删除</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>Qwen3-Instruct 8B/14B/32B</code>；Summarizer与Executor使用相同LLM。</li><li>AppWorld 90 Train构建Memory，168 Test-N；每个训练任务采样8条轨迹。</li><li>Temperature 0.9；Top-K 5；最多30 Execution Iterations。</li><li>8条轨迹是Memory Construction Budget，不是RL Group Size。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Qwen3-8B：<code>14.97/32.85</code> → <code>24.70/42.06 Avg@4/Pass@4</code>。</li><li>Qwen3-14B：<code>22.57/41.07</code> → <code>34.32/52.98</code>。</li><li>Qwen3-32B：<code>27.23/50.59</code> → <code>42.02/63.49</code>。</li><li>Qwen8B平均Latency从21.42增加到23.96秒/任务。</li></ul></div><h3 id="_2606-metis-bridging-text-and-code-memory" tabindex="-1">(2606) METIS: Bridging Text and Code Memory <a class="header-anchor" href="#_2606-metis-bridging-text-and-code-memory" aria-label="Permalink to &quot;(2606) METIS: Bridging Text and Code Memory&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Text Memory易构建和迁移，但每次执行都要重新读Context；Code Memory执行快，但构建昂贵、跨任务脆弱。</li><li><strong>Motivation</strong>：先用Text作为低成本暂存层，只将高频稳定Plan选择性“结晶”为Callable Tool。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>Text层保存<code>Plan、Environment Fact和Pitfall</code>。</li><li>Plan被不同Query反复选中后通过<code>Recurrence Gate</code>触发Code化。</li><li>Codifier只看Plan与Query，经<code>Dependency Closure + Sandbox Compile</code>和一次修复后入库。</li><li><code>Memory Manager</code>联合检索Text与Tool。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：<code>GPT-4o ReAct Executor + Claude Sonnet 4.6 Reflector</code>；Embedding为text-embedding-3-large。</li><li>90 Train按固定顺序构建Memory，Freeze后评测Test-N。</li><li>另做Task-level Resampled Split；明确不评测Test-C。</li><li>关键Recurrence Threshold、Top-k和最大Step Budget未报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Official Split：No-memory TGC/Tokens/Turns为<code>51.8/112.6K/14.55</code>，METIS为<code>60.1/97.4K/11.25</code>。</li><li>Resampled：No-memory <code>54.8</code>，METIS <code>66.1 TGC</code>。</li><li>Dev消融：Text-only 62.3、Code-only 60.2、Eager 63.2、Full 66.7。</li><li>Eager Code化成本更高且准确率更低，说明不是Tool越多越好。</li></ul></div><h2 id="九、上下文压缩" tabindex="-1">九、上下文压缩 <a class="header-anchor" href="#九、上下文压缩" aria-label="Permalink to &quot;九、上下文压缩&quot;">​</a></h2><h3 id="_2510-acon-optimizing-context-compression" tabindex="-1">(2510) ACON: Optimizing Context Compression <a class="header-anchor" href="#_2510-acon-optimizing-context-compression" aria-label="Permalink to &quot;(2510) ACON: Optimizing Context Compression&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>长程历史持续增长，带来Token/显存开销和Attention Dilution。</li><li>启发式压缩容易误删信息，独立Compressor调用又可能增加Latency。</li><li><strong>Motivation</strong>：冻结Agent，通过执行反馈自动优化Compression Guideline，并蒸馏给小模型。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>History超过<code>4,096 Tokens</code>时压缩历史，Observation超过<code>1,024 Tokens</code>时单独压缩。</li><li>从<code>无压缩成功、压缩失败</code>的对比轨迹产生反馈。</li><li><code>Utility Optimization + Compression Optimization</code>更新Guideline，再蒸馏到Qwen3/Phi-4 Compressor。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：Agent/Compressor为<code>GPT-4.1</code>，Optimizer为o3；AppWorld 90 Train、168 Test-N。</li><li>每个训练任务收集Compressed/Uncompressed两条轨迹；每轮采样5个Candidate Prompt。</li><li>Student LoRA Rank 16、LR <code>1e-4</code>、3 Epoch、1×A100-80G。</li><li>主Agent Policy不更新，推理保留独立Compressor。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>GPT-4.1 No Compression：TGC <code>56.0</code>、Peak <code>9.93K</code>。</li><li>History ACON：TGC <code>56.5</code>、Peak <code>7.33K</code>；Observation ACON为<code>53.6/7.43K</code>。</li><li>GPT-4.1 Agent + Qwen14B Compressor降低美元成本，但Latency从73.24秒增至87.68/101.92秒。</li></ul></div><h3 id="_2512-paace-plan-aware-context-engineering" tabindex="-1">(2512) PAACE: Plan-Aware Context Engineering <a class="header-anchor" href="#_2512-paace-plan-aware-context-engineering" aria-label="Permalink to &quot;(2512) PAACE: Plan-Aware Context Engineering&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>普通摘要、FIFO和Query-aware Compression只看当前问题，没有显式考虑未来Plan的变量与依赖。</li><li><strong>Motivation</strong>：学习一个以未来<code>k</code>个Plan Step为条件的压缩策略，保留后续Workflow真正需要的信息。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>PAACE-Syn</code>生成5–30 Step的合成Workflow与噪声Context。</li><li><code>GPT-OSS-120B</code>根据完整Context和Next-k Plan生成压缩文本。</li><li>用<code>重执行 + Embedding相似度 + LLM Judge</code>过滤，再蒸馏到Qwen3-4B。</li><li>推理每一步调用<code>Compressor + Future Plan</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：Teacher <code>GPT-OSS-120B</code>，Student <code>Qwen3-4B-Instruct</code>。</li><li><strong>数据规模</strong>：约<code>120万Synthetic Workflow</code>、压缩前约<code>95亿Tokens</code>。</li><li>使用Causal LM Loss做监督蒸馏，不是PPO/GRPO。</li><li>AppWorld Agent Backbone、任务数、Split和运行次数未完整报告。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>论文使用自定义Easy/Medium/Hard平均Acc，不是官方TGC/SGC。</li><li>No Compression：Acc <code>56.0</code>、Peak <code>9.93K</code>；PAACE：<code>59.0/6.23K</code>。</li><li><code>k=1/2/3</code>的Acc为<code>56.5/59.0/58.6</code>。</li><li>论文报告Student保留Teacher约97–98%性能。</li></ul></div><h2 id="十、多agent、企业系统与广义规划" tabindex="-1">十、多Agent、企业系统与广义规划 <a class="header-anchor" href="#十、多agent、企业系统与广义规划" aria-label="Permalink to &quot;十、多Agent、企业系统与广义规划&quot;">​</a></h2><h3 id="_2509-prost-progressive-sub-task-training-for-multi-agent-systems" tabindex="-1">(2509) ProST: Progressive Sub-task Training for Multi-Agent Systems <a class="header-anchor" href="#_2509-prost-progressive-sub-task-training-for-multi-agent-systems" aria-label="Permalink to &quot;(2509) ProST: Progressive Sub-task Training for Multi-Agent Systems&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>小模型用普通SFT难以一次掌握长轨迹的规划、执行和检查能力。</li><li>多Agent可以分工，但增加推理成本，需要在效果与FLOPs之间权衡。</li><li><strong>Motivation</strong>：用课程式SFT逐步训练Orchestrator、Executor和Critic。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li><code>Llama-3.3-70B</code>生成单Agent轨迹，<code>Claude-3.7-Sonnet</code>改写并验证为三Agent轨迹。</li><li><code>ProST</code>在5个Epoch中逐步加入Task-specific Subtask，并Mask错误Step。</li><li>推理保留<code>Orchestrator–Executor–Critic</code>三角色系统。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>数据规模</strong>：使用AppWorld Train+Dev <code>147 Tasks</code>，得到<code>2,844条单Agent和2,708条多Agent轨迹</code>。</li><li><strong>模型</strong>：<code>Qwen2.5-Coder 7B/14B/32B、Llama-3.1-8B、Phi-4-14B</code>。</li><li>LoRA Rank 16、LR <code>2e-4</code>、5 Epoch、Max Sequence 20,480；4×H100。</li><li>方法是SFT而非RL，<code>rollout.n</code>与Reward不适用。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Test-N：Qwen14B <code>42.3/26.8</code>，Phi-4 <code>46.4/28.6</code>，Llama8B <code>32.7/19.6</code>。</li><li>Test-C：Qwen14B <code>14.1/5.8</code>，Phi-4 <code>17.8/8.6</code>。</li><li>结果来自训练后的多Agent系统，不能等同于单Policy模型能力。</li></ul></div><h3 id="_2510-cuga-ibm-generalist-agent" tabindex="-1">(2510) CUGA: IBM Generalist Agent <a class="header-anchor" href="#_2510-cuga-ibm-generalist-agent" aria-label="Permalink to &quot;(2510) CUGA: IBM Generalist Agent&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>企业Agent不仅要求Benchmark Success，还要求跨API/Web/CLI、可审计、可治理和故障恢复。</li><li>单一ReAct难以同时满足这些生产约束。</li><li><strong>Motivation</strong>：构建能从研究Benchmark延展到企业部署的Generalist Agent System。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>外层<code>Task Analyzer / Decomposer / Plan Controller</code>维护Durable Ledger。</li><li>内层包含<code>API / Web / CLI / Domain Agent</code>。</li><li>额外使用<code>API Shortlister、Code Planner、Sandbox、Schema Validation、Reflective Retry和Provenance Log</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>模型</strong>：AppWorld Backbone为<code>GPT-4.1</code>；无SFT/RL。</li><li>未报告统一Max Turns/Tokens；实际平均交互数Test-N 10.69、Test-C 8.40。</li><li>多Agent、检索、Sandbox和验证全部保留在推理路径。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Test-N <code>73.2/62.5 TGC/SGC</code>，Test-C <code>57.6/48.2</code>。</li><li>Test-N L1/L2/L3 TGC为<code>91.2/77.1/54.0</code>；Test-C为<code>91.7/58.7/44.1</code>。</li><li>高分同时来自模型与厚系统架构，不能作为纯Policy训练基线。</li></ul></div><h3 id="_2605-hcl-gp-hierarchical-generalized-planning" tabindex="-1">(2605) HCL-GP: Hierarchical Generalized Planning <a class="header-anchor" href="#_2605-hcl-gp-hierarchical-generalized-planning" aria-label="Permalink to &quot;(2605) HCL-GP: Hierarchical Generalized Planning&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景 &amp; Motivation</div><ul><li>Interactive Coding Agent逐Task重复发现相似Workflow，无法利用同Scenario任务共享结构。</li><li><strong>Motivation</strong>：将Generalized Planning与HTN式分解实现为参数化Python Policy和可复用Component。</li></ul></div><div class="custom-block note"><div class="custom-block-title">核心方法</div><ul><li>同时读取一个Scenario的多个Task，抽象<code>共享Step、Policy Signature和Parameter Binding</code>。</li><li>检索历史Component，生成<code>参数化Policy</code>，并在全部Task Instance上执行、验证和Debug。</li><li>成功Policy再<code>自动分解、泛化、去重</code>并写入Repository。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">实验设置</div><ul><li><strong>构建数据</strong>：<code>30 Train Scenarios、90 Tasks</code>；Claude两轮构建出<code>101→159个Component</code>。</li><li><strong>测试模型</strong>：<code>Claude Sonnet 4.6</code>与<code>GPT-OSS-120B</code>。</li><li>Top-20 Component + Top-20 API；Clustering Threshold 0.85；每轮最多3次Debug。</li><li>无权重训练，无RL <code>rollout.n</code>；测试时持续使用Verifier与Repository。</li></ul></div><div class="custom-block important"><div class="custom-block-title">关键结果</div><ul><li>Claude HCL-GP：Test-N <code>98.2/98.2</code>，Test-C <code>98.3/97.8</code>。</li><li>无复用Claude GP为N <code>96.4/96.4</code>、C <code>83.2/82.0</code>。</li><li>GPT-OSS HCL-GP为N <code>62.5/62.5</code>、C <code>41.0/41.0</code>；无复用时接近0。</li><li>方法一次读取Scenario多个测试任务并多轮Debug，98%不能与标准逐Task AgentRL直接比较。</li></ul></div><h2 id="十一、横向比较与本文定位" tabindex="-1">十一、横向比较与本文定位 <a class="header-anchor" href="#十一、横向比较与本文定位" aria-label="Permalink to &quot;十一、横向比较与本文定位&quot;">​</a></h2><h3 id="_11-1-能力到底来自哪里" tabindex="-1">11.1 能力到底来自哪里 <a class="header-anchor" href="#_11-1-能力到底来自哪里" aria-label="Permalink to &quot;11.1 能力到底来自哪里&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力来源</th><th>代表工作</th><th>优点</th><th>主要代价</th></tr></thead><tbody><tr><td><strong>Policy Update</strong></td><td><strong>LOOP、SALT、GVPO、本文</strong></td><td>推理简单，能直接测量参数能力</td><td><strong>环境Rollout贵，长轨迹训练不稳定</strong></td></tr><tr><td><strong>训练期经验与Skill增强RL</strong></td><td><strong>SIRI、Skill-SD、SAGE、AgentEvolver</strong></td><td>可利用Skill或经验增强Policy训练</td><td><strong>训练链路复杂；SAGE推理期仍依赖外部Skill Library</strong></td></tr><tr><td><strong>Task Distribution</strong></td><td><strong>CuES、CoEvolve</strong></td><td>缓解任务不足与覆盖问题</td><td><strong>数据质量控制和外部探索成本高</strong></td></tr><tr><td><strong>External Skill/Memory</strong></td><td><strong>SkillX、ASSAY、ICL、ACE、ReMe、METIS</strong></td><td>更新快、可持续积累</td><td><strong>检索错误、Context成本、系统状态复杂</strong></td></tr><tr><td><strong>Context Compressor</strong></td><td><strong>ACON、PAACE</strong></td><td>降低Token与Context Rot</td><td><strong>额外模型调用和Latency</strong></td></tr><tr><td><strong>Agent Architecture</strong></td><td><strong>ProST、CUGA、HCL-GP</strong></td><td>规划、验证和复用能力强</td><td><strong>难隔离Policy能力，协议与成本不统一</strong></td></tr></tbody></table><h3 id="_11-2-本文建议定位" tabindex="-1">11.2 本文建议定位 <a class="header-anchor" href="#_11-2-本文建议定位" aria-label="Permalink to &quot;11.2 本文建议定位&quot;">​</a></h3><div class="custom-block note"><div class="custom-block-title">A Simple and Strong AgentRL Training Stack</div><p><strong>核心研究问题</strong></p><ul><li>当<code>经验生成、结果验证、长轨迹更新</code>被联合设计后，仅依靠环境交互RL，单Policy Agent能提升到什么程度？</li></ul><p><strong>三阶段闭环</strong></p><ol><li><code>Current-policy Experience Generation</code>：混合全部L1/L2/L3任务，同任务32条Thinking Rollout；环境每轮最多返回4K Tokens，LLM单次生成不设独立上限。</li><li><code>Exact Outcome Verification</code>：全部Required Tests通过才给1，否则为0；没有Intermediate Reward，也没有Intermediate Advantage。</li><li><code>Fresh and Conservative Update</code>：错误轨迹隔离并做Fake Data处理；使用Env Loss Mask，仅对Policy Token采用DAPO Token-Level Loss（Token-mean），一次Fresh Update，配合对称Clip与KL Anchor，且不加Entropy Reward。</li></ol><p><strong>最直接相关工作</strong></p><ul><li>普通Outcome AgentRL：LOOP。</li><li>Step Credit与Process Feedback：SALT、GVPO。</li><li>Skill/经验增强RL：SIRI、Skill-SD、SAGE、AgentEvolver。</li></ul></div><h3 id="_11-3-本文实验事实核对卡" tabindex="-1">11.3 本文实验事实核对卡 <a class="header-anchor" href="#_11-3-本文实验事实核对卡" aria-label="Permalink to &quot;11.3 本文实验事实核对卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>本文设置/结果</th><th>写作边界</th></tr></thead><tbody><tr><td><strong>Backbone</strong></td><td><strong>Qwen3-14B</strong>，无AppWorld Domain SFT</td><td>不写成新模型或新Optimizer</td></tr><tr><td><strong>训练数据</strong></td><td><strong>全部90 Tasks</strong>；L1/L2/L3=<strong>36/36/18</strong></td><td><strong>w/o L3同时改变任务数与计算量</strong>，不能只归因为难度</td></tr><tr><td><strong>Loss / Mask</strong></td><td><strong>DAPO Token-Level Loss（Token-mean）；Env Loss Mask；仅Policy Token</strong></td><td>是行业常规实现，<strong>不单独包装成算法创新</strong></td></tr><tr><td><strong>Clip / KL / Entropy</strong></td><td><strong>GRPO Clip-Low/High=0.2/0.2；KL Loss=1e-4；No Entropy Reward</strong></td><td>KL用于<strong>后期训练稳定</strong>；不写成新正则项</td></tr><tr><td><strong>Reward / Advantage</strong></td><td><strong>All-or-Nothing Terminal Reward</strong>；全部正确为1，否则为0；无Intermediate Reward/Advantage</td><td>是整体流程组件，<strong>不是唯一创新</strong>；与LOOP Pass Fraction区分</td></tr><tr><td><strong>Policy Freshness</strong></td><td><strong>Strict On-policy；ppo_epochs=1</strong>；每批Fresh Rollout只更新一次</td><td>不写成提出On-policy RL，强调避免长轨迹Staleness</td></tr><tr><td><strong>Rollout / Mode</strong></td><td><strong>n=32；Thinking Mode；50 Turns</strong></td><td>没有Matched n Sweep，<strong>不能宣称32最优</strong></td></tr><tr><td><strong>Generation / Environment</strong></td><td><strong>Environment单次返回上限4K Tokens；LLM单次生成不设独立上限；总Response Cap 32K</strong></td><td>“单次不设限”不等于无限总预算，必须同时写清总Cap</td></tr><tr><td><strong>Invalid Trajectory</strong></td><td><strong>丢弃错误轨迹，并做Fake Data处理</strong></td><td>需要在Methods中定义错误判定与Fake Data用途，避免被理解为Reward Filtering</td></tr><tr><td><strong>Optimizer</strong></td><td><strong>GRPO；LR 3e-6</strong></td><td><strong>不称为新GRPO</strong>，强调训练配置协同</td></tr><tr><td><strong>Matched mean@4</strong></td><td>Base→RL：Dev <strong>32.02→87.72</strong>；Test-N <strong>32.44→83.18</strong>；Test-C <strong>19.66→66.13</strong></td><td><strong>不能与Official mean@1混用</strong></td></tr><tr><td><strong>历史官方结果</strong></td><td>Test-N <strong>86.9/80.4</strong>；Test-C <strong>67.6/50.4</strong></td><td>写<strong>2026年2月历史强结果</strong>，不写Current SOTA</td></tr><tr><td><strong>SWE补充</strong></td><td><strong>Qwen3.5-9B</strong>，<strong>31.3→47.9 mean@4</strong></td><td><strong>只作为初步迁移证据</strong></td></tr></tbody></table><h3 id="_11-4-不应使用的包装" tabindex="-1">11.4 不应使用的包装 <a class="header-anchor" href="#_11-4-不应使用的包装" aria-label="Permalink to &quot;11.4 不应使用的包装&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">Claim边界</div><ul><li>不写“现有工作都依赖臃肿Scaffold”；LOOP、SALT、GVPO、Skill-SD和SIRI都能保持简单推理。</li><li>不把Binary Reward包装成完整方法；GVPO说明Process Reward有效，LOOP也说明Fractional Reward可以训练。</li><li>不把<code>Env Loss Mask</code>或<code>DAPO Token-Level Loss（Token-mean）</code>单独写成创新；它们是与行业常见AgentRL一致的训练规则。</li><li>不把“LLM单次生成不设限”写成无限Context或无限总生成；本文仍有<code>32K总Response Cap</code>与50轮交互预算。</li><li><code>KL Loss</code>应写成后期稳定器，不写成主要方法贡献；No-KL消融用于支持稳定性作用。</li><li>不声称<code>rollout.n=32</code>已经被证明最优。</li><li>不写Current SOTA、训练Reward精确等于1，或已经证明跨领域普适性。</li><li>推荐表述：<code>without auxiliary learned or retrieval-based inference modules beyond the standard environment interface</code>。</li></ul></div>',112))])}const S=n(r,[["render",g]]);export{T as __pageData,S as default};
